use crate::{market::MarketMetrics,strategy::OpportunityScore};use serde::{Deserialize,Serialize};#[derive(Debug,Clone,Serialize,Deserialize)]pub struct TargetScenario{pub multiple:f64,pub target_price_sol:Option<f64>}#[derive(Debug,Clone,Serialize,Deserialize)]pub struct TradeSignal{pub mint:String,pub status:String,pub score:f64,pub reasons:Vec<String>,pub scenarios:Vec<TargetScenario>,pub observed_price_sol:Option<f64>}pub fn build(mint:&str,o:&OpportunityScore,m:&MarketMetrics)->TradeSignal{let scenarios=[2.0,5.0,10.0,25.0,50.0,100.0].into_iter().map(|x|TargetScenario{multiple:x,target_price_sol:m.price_sol.map(|p|p*x)}).collect();TradeSignal{mint:mint.into(),status:format!("{:?}",o.decision),score:o.score,reasons:o.reasons.clone(),scenarios,observed_price_sol:m.price_sol}}